'use strict';
// Review-only detailed pixel presentation. The world and normal encounters keep their art.
function guidedCombatScene(c){
 const revealed=c.phase==='reveal',ended=c.phase==='result',r=c.result,p=c.player,e=c.enemy;
 const melee=revealed&&r.playerCards.some(n=>n.startsWith('Melee'));
 const magic=revealed&&r.playerCards.some(n=>/Bolt|Spark|Seal/.test(n));
 const tusks=revealed&&r.enemyCards.some(n=>n.startsWith('Tusk'));
 const stats=(fighter,side)=>`<div class="arena-hud arena-hud-${side}"><strong>${escapeText(fighter.name)}</strong><div class="arena-health"><i style="width:${fighter.hp/fighter.maxHP*100}%;--hp-before:${(c.beforeHP?.[side]??fighter.hp)/fighter.maxHP*100}%"></i></div><span>${fighter.hp} / ${fighter.maxHP} HP <small>${side==='player'?`· ${fighter.mana} mana · ✦ ${fighter.dice}`:revealed?'· Hand revealed':ended?'· Encounter ended':'· Hand hidden'}</small></span></div>`;
 const effect=side=>{if(!revealed)return '';const v=r[side];return `<span class="arena-damage">${v.damage?'-'+v.damage:v.blocked?'BLOCK':''}</span>${v.blocked?`<span class="arena-block">${v.blocked} blocked</span>`:''}${v.healed?`<span class="arena-heal">+${v.healed} HP</span>`:''}${v.blocked?'<div class="guided-shield"></div>':''}`};
 return `<section class="combat-arena guided-stage ${revealed?'round-resolved':''} ${ended?'guided-ended':''} ${preferences.reduceMotion?'arena-reduced-motion':''}" aria-label="Detailed pixel-art woodland encounter">
 <img class="guided-backdrop" src="assets/guided/clearing.png" alt="Sunlit forest clearing with a broad woodland path"><div class="guided-shade"></div>
 <div class="arena-location"><span>THE FOREST EDGE</span><small>GUIDED ENCOUNTER · ${ended?'AFTERMATH':'ROUND '+c.round}</small></div>${stats(p,'player')}${stats(e,'enemy')}
 <div class="guided-actor guided-hero ${revealed&&r.player.damage?'guided-hit':''} ${p.hp===0?'guided-fallen':''}"><div class="guided-shadow"></div><img class="guided-sprite" src="assets/guided/adventurer.png" alt="Detailed pixel-art adventurer in a green cloak and leather boots">${!magic||melee?`<svg class="guided-weapon ${melee?'weapon-swing':''}" viewBox="0 0 100 100" aria-hidden="true" shape-rendering="crispEdges"><path d="M45 69V14l5-9 5 9v55z" fill="#e0e9ef" stroke="#303842" stroke-width="3"/><path d="M45 18h4v48h-4z" fill="#9eb0c4"/><path d="M34 68h32v7H34z" fill="#d9ac60" stroke="#51412d" stroke-width="2"/><path d="M46 76h8v17h-8z" fill="#6c432d"/><path d="M44 92h12v5H44z" fill="#d4a865"/></svg>`:''}${effect('player')}</div>
 <div class="guided-actor guided-boar ${revealed&&r.enemy.damage?'guided-hit':''} ${e.hp===0?'guided-fallen':''}"><div class="guided-shadow"></div><img class="guided-sprite" src="assets/guided/boar.png" alt="Detailed pixel-art wild boar with shaded fur and ivory tusks">${effect('enemy')}</div>
 ${melee?'<div class="guided-wave guided-sword-wave" aria-label="Sword slash wave"><svg viewBox="0 0 80 140"><path d="M15 8Q101 70 15 132Q58 73 15 8Z" fill="#fff0c1"/><path d="M10 20Q76 70 10 120" fill="none" stroke="#d7ad65" stroke-width="4"/></svg></div>':''}
 ${magic?'<div class="guided-magic" aria-label="Arcane projectile"><i></i></div>':''}
 ${tusks?'<div class="guided-wave guided-tusk-wave" aria-label="Boar tusk shockwave"><svg viewBox="0 0 100 100"><path d="M85 20Q12 16 10 68Q37 38 85 20ZM85 48Q30 40 22 95Q42 64 85 48Z" fill="#f8e3bd" stroke="#a67b4a" stroke-width="2"/></svg></div>':''}
 ${revealed?'<div class="guided-contact contact-hero"></div><div class="guided-contact contact-boar"></div>':''}
 <div class="arena-bottom-caption">${ended?({victory:'The path is clear.',defeat:'Your journey continues at the hearth.',draw:'The forest falls quiet.',escaped:'You find a way back to the trail.',negotiated:'The boar steps aside.'}[c.endOutcome]):revealed?'Both hands resolve together.':'Choose your hand. Both fighters hold their ground.'}</div></section>`;
}
function showCombatSurface(html,guided=false){if(!guided){showModal(html);return}dismissSpeech();keys.clear();clickTarget=null;if($('modal').open)$('modal').close();$('modalContent').innerHTML='';setLifeMode('guided');$('opening').hidden=true;const panel=$('guidedCombat');panel.hidden=false;panel.innerHTML=html;if(/guided-aftermath|encounter-intro|guided-map-screen/.test(html))panel.scrollTop=0;const images=[...panel.querySelectorAll('img')];panel.classList.remove('guided-assets-loading');if(images.some(img=>!img.complete)){panel.classList.add('guided-assets-loading');const ready=()=>{if(images.every(img=>img.complete))panel.classList.remove('guided-assets-loading')};for(const img of images){img.addEventListener('load',ready,{once:true});img.addEventListener('error',ready,{once:true})}}panel.focus();document.body.classList.add('in-guided')}
function closeGuidedSurface(){const panel=$('guidedCombat');panel.hidden=true;panel.innerHTML='';document.body.classList.remove('in-guided')}
function renderGuidedOutcome(c,outcome){c.phase='result';c.endOutcome=outcome;const title={victory:'The boar yields the trail.',defeat:'A retreat to the hearth.',draw:'Both fighters fall.',escaped:'Back to the trail.',negotiated:'A peaceful passage.'}[outcome];const detail=outcome==='victory'?'The boar withdraws into the trees. In a world encounter, this enemy would stay cleared and your rewards would appear on the map.':outcome==='defeat'||outcome==='draw'?'The scene fades as the village comes into view. In a world encounter, your Vault would protect your progress and be consumed, or the current reincarnation rules would apply.':'The encounter ends without another exchange. You return to the map and continue your journey.';
 showCombatSurface(`${guidedCombatScene(c)}<div class="guided-aftermath"><div class="eyebrow">THE ENCOUNTER BECOMES PART OF YOUR JOURNEY</div><h2>${title}</h2><p>${detail}</p><div class="guided-result-actions"><button class="primary" id="previewMapReturn">Preview the map transition →</button><button class="quiet" id="retryGuided">Try another hand</button><button class="quiet" id="leaveGuidedResult">Main menu</button></div><small>Guided practice · no health, items, rewards or progress changed in your saved world.</small></div>`,true);
 $('previewMapReturn').onclick=()=>renderGuidedMapPreview(c);$('retryGuided').onclick=()=>{startCombat({name:'Forest edge',enemyType:'boar',practice:true,guided:true,encounter:true});combat.player.hp=combat.player.maxHP;combat.player.mana=maxMana();renderCombat()};$('leaveGuidedResult').onclick=leavePractice;
}
function renderGuidedMapPreview(c){const home=['defeat','draw'].includes(c.endOutcome),cleared=['victory','negotiated'].includes(c.endOutcome);showCombatSurface(`<div class="guided-map-screen"><div class="eyebrow">MAP TRANSITION PREVIEW · PRACTICE</div><h2>${home?'You return to Hearthstead.':cleared?'You continue from the forest edge.':'You retreat to the trail.'}</h2><p>${home?'Your character reappears inside the safe village. The opponent remains in the wilderness.':cleared?'The encounter is cleared here. You remain on the trail, ready to continue exploring.':'You escaped. The opponent remains in the forest, and you can return when ready.'}</p><svg class="guided-map" viewBox="0 0 900 420" role="img" aria-label="Map consequence preview with a safe village on the left and a forest encounter on the right"><rect width="900" height="420" rx="20" fill="#61734d"/><path d="M0 230Q180 145 340 220T900 160" stroke="#c9b47d" stroke-width="52" fill="none"/><path d="M70 70h240v285H70z" rx="20" fill="#8d9a6c"/>${[100,205,155].map((x,i)=>`<g transform="translate(${x} ${95+i*68})"><path d="M0 25h55v45H0z" fill="#c7b38b"/><path d="M-8 26L28 0l36 26Z" fill="#80593e"/><path d="M22 45h12v25H22z" fill="#544731"/></g>`).join('')}${[450,520,600,690,760,820].map((x,i)=>`<g transform="translate(${x} ${40+i%2*220})"><path d="M15 30h12v65H15z" fill="#614e35"/><path d="M20 0L-10 65h65Z" fill="#294d36"/></g>`).join('')}<circle cx="${home?180:cleared?650:480}" cy="${home?220:190}" r="18" fill="#edda93" stroke="#fff3c9" stroke-width="5"/><text x="180" y="385" fill="#f1e7c8" text-anchor="middle" font-size="20">Hearthstead · safe village</text><text x="650" y="385" fill="#f1e7c8" text-anchor="middle" font-size="20">${cleared?'Encounter cleared':'Opponent remains here'}</text></svg><p class="guided-map-note">This is a consequence preview. Your actual map and saved journey have not been changed.</p><div class="guided-result-actions"><button class="primary" id="returnFromMapDemo">Back to the guided encounter</button><button class="quiet" id="mapDemoMenu">Main menu</button></div></div>`,true);$('returnFromMapDemo').onclick=showEncounterWalkthrough;$('mapDemoMenu').onclick=leavePractice}
